CONFIG={'producer_root': '/data4/researcher/h3_runs/timing_oxygen_online_r133_20261020', 'audit_file': '/data4/researcher/h3_runs/oxygen_online_recovery_metrics_r138_20261020/ACTUAL_AUDIT_COMPACT.json', 'audit_sha256': '9bcdd4884c99311398a8f2561f77dce7cf1bdfbb2dd4ebf1ee1db56a6dab092e', 'source_pose': '/data4/researcher/h3_runs/timing_oxygen_online_r133_20261020/configs/source.pose.json', 'source_pose_sha256': '6bcdf84ce27e522d5d5e9de4ef24f2202b12b1ff3823543376c257bbb4f2b07f', 'helper_sources': {'diagnose': {'source': '"""Offline identifiability diagnostic; no producer, threshold or controller changes."""\nfrom pathlib import Path\nimport json, hashlib, sys\nimport numpy as np\nROOT = Path(__file__).resolve().parent\n\n\ndef digest(p):\n    return hashlib.sha256(Path(p).read_bytes()).hexdigest()\n\n\ndef directions(path, threshold):\n    data = json.loads(Path(path).read_text())\n    frames = data[\'frames\'][:98]\n    xy = np.full((len(frames), 17, 2), np.nan)\n    confidence = np.zeros((len(frames), 17))\n    for t, row in enumerate(frames):\n        selected = row[\'selected_person\']\n        if selected is not None:\n            person = row[\'persons\'][selected]\n            xy[t] = person[\'coco17_xy\']\n            confidence[t] = person[\'coco17_score\']\n    delta = np.stack([xy[:, b]-xy[:, a] for a,b in [(5,7),(7,9),(6,8),(8,10)]], axis=1)\n    conf = np.stack([np.minimum(confidence[:, a],confidence[:, b]) for a,b in [(5,7),(7,9),(6,8),(8,10)]], axis=1)\n    lengths = np.linalg.norm(delta,axis=-1)\n    vectors = delta/np.maximum(lengths[...,None],1e-12)\n    vectors[(conf<threshold)|(lengths<=1e-8)] = np.nan\n    return vectors, conf\n\n\ndef costs(a,b,w):\n    valid = np.isfinite(a).all(-1)&np.isfinite(b).all(-1)&np.isfinite(w)&(w>0)\n    weights = np.where(valid,w,0)\n    aa=np.where(valid[...,None],a,0); bb=np.where(valid[...,None],b,0)\n    sums=weights.sum(axis=0); total=float(sums.sum())\n    if total<=0: return None\n    am=(weights[...,None]*aa).sum(axis=0)/np.maximum(sums[:,None],1e-12)\n    bm=(weights[...,None]*bb).sum(axis=0)/np.maximum(sums[:,None],1e-12)\n    ac=np.where(valid[...,None],a-am,0);bc=np.where(valid[...,None],b-bm,0)\n    mse_a=float((weights*np.sum(ac*ac,axis=-1)).sum()/total)\n    mse_b=float((weights*np.sum(bc*bc,axis=-1)).sum()/total)\n    raw=float((weights*np.linalg.norm(aa-bb,axis=-1)).sum()/total)\n    centered=float((weights*np.linalg.norm(ac-bc,axis=-1)).sum()/total)\n    offset=float((sums*np.linalg.norm(am-bm,axis=-1)).sum()/total)\n    correlation=None if mse_a*mse_b<=1e-20 else float((weights*np.sum(ac*bc,axis=-1)).sum()/total/np.sqrt(mse_a*mse_b))\n    return {\'weighted_direction_error\':raw,\'centered_direction_error\':centered,\'mean_direction_offset\':offset,\'source_direction_rms_variation\':float(np.sqrt(mse_a)),\'target_direction_rms_variation\':float(np.sqrt(mse_b)),\'centered_vector_correlation\':correlation,\'valid_entries\':int(valid.sum()),\'valid_fraction\':float(valid.mean())}\n\n\ndef curve(source, target, window, arm, threshold):\n    a,ca=source;b,cb=target\n    joints={\'left\':[0,1],\'right\':[2,3],\'both\':[0,1,2,3]}[arm]\n    output=[]\n    for lag in range(-24,25):\n        t=np.arange(window[0],window[1]+1)\n        t=t[(t+lag>=0)&(t+lag<len(b))]\n        if len(t)<.8*(window[1]-window[0]+1):continue\n        u=t+lag\n        aa=a[t][:,joints];bb=b[u][:,joints]\n        w=np.minimum(ca[t][:,joints],cb[u][:,joints])\n        w=np.where(w>=threshold,w,0)\n        entry=costs(aa,bb,w)\n        if entry is not None:output.append({\'lag\':lag,\'retained_source_frames\':t.tolist(),**entry})\n    return output\n\n\ndef sanity():\n    t=np.arange(32,dtype=float)\n    a=np.stack([np.cos(t*.3),np.sin(t*.3)],axis=-1)[:,None,:]\n    w=np.ones((32,1))\n    assert costs(a,a,w)[\'weighted_direction_error\']==0\n    offset=np.array([.5,-.4])[None,None,:]\n    r=costs(a,a+offset,w)\n    assert r[\'weighted_direction_error\']>.6 and r[\'centered_direction_error\']<1e-14\n    flat=np.zeros_like(a)\n    assert costs(flat,flat,w)[\'centered_vector_correlation\'] is None\n    conf=np.ones((len(a),1));curve_rows=curve((np.repeat(a,4,axis=1),np.repeat(conf,4,axis=1)),(np.repeat(np.roll(a,3,axis=0),4,axis=1),np.repeat(conf,4,axis=1)),[5,20],\'left\',.5)\n    assert min(curve_rows,key=lambda r:r[\'weighted_direction_error\'])[\'lag\']==3\n\n\ndef main():\n    sanity()\n    source=ROOT/\'inputs/source.pose.json\';target=ROOT/\'inputs/index10.pose.json\'\n    cases=[(\'early_selected\',[4,19],\'left\'),(\'action_selected\',[44,59],\'left\'),(\'action_right\',[40,55],\'right\')]\n    result={\'scope\':\'Post-hoc diagnostic on frozen source and index10 ordinary prediction. Source self-comparison and centered cost are diagnostics only. No controller output or inference changed.\',\'input_sha256\':{str(source):digest(source),str(target):digest(target)},\'script_sha256\':digest(__file__),\'rows\':[],\'sanity_checks_passed\':4}\n    for c in [.3,.5]:\n        s=directions(source,c);p=directions(target,c)\n        for label,window,arm in cases:\n            result[\'rows\'].append({\'name\':label,\'window\':window,\'arm\':arm,\'confidence\':c,\'source_to_prediction\':curve(s,p,window,arm,c),\'source_self\':curve(s,s,window,arm,c)})\n    (ROOT/\'RESULT.json\').write_text(json.dumps(result,indent=2,allow_nan=False)+\'\\n\')\n    for row in result[\'rows\']:\n        values={x[\'lag\']:x for x in row[\'source_to_prediction\']}\n        v=values[0];best=min(values.values(),key=lambda x:x[\'weighted_direction_error\'])\n        print(json.dumps({\'name\':row[\'name\'],\'confidence\':row[\'confidence\'],\'source_rms\':v[\'source_direction_rms_variation\'],\'zero_error\':v[\'weighted_direction_error\'],\'zero_centered\':v[\'centered_direction_error\'],\'raw_best_lag\':best[\'lag\'],\'best_error\':best[\'weighted_direction_error\'],\'best_centered\':best[\'centered_direction_error\'],\'centered_best_lag\':min(values.values(),key=lambda x:x[\'centered_direction_error\'])[\'lag\']}))\n\nif __name__==\'__main__\':\n    if \'--sanity\' in sys.argv:\n        sanity();print(\'4 diagnostic sanity checks passed\')\n    else:main()\n', 'sha256': '7d63f463d2940bcbe610774a1cc85ee9ead4e0595dd31b9c4cb1fe805df4bee1', 'original_path': '/Users/researcher/DevProjects/h3-source-temporal-observability-20261020/diagnose.py'}, 'check_centered_support': {'source': '"""Compare frozen proposals with a nuisance-offset diagnostic on common support."""\nfrom pathlib import Path\nimport json\nimport numpy as np\nimport diagnose as d\nROOT=Path(__file__).resolve().parent\n\n\ndef at(features, indices, joints):\n    x,c=features\n    valid=(indices>=0)&(indices<len(x))\n    values=np.full((len(indices),len(joints),2),np.nan)\n    confidence=np.zeros((len(indices),len(joints)))\n    values[valid]=x[indices[valid]][:,joints]\n    confidence[valid]=c[indices[valid]][:,joints]\n    return values,confidence\n\n\ndef compare(source,target,window,arm,lag,threshold):\n    joints={\'left\':[0,1],\'right\':[2,3],\'both\':[0,1,2,3]}[arm]\n    indices=np.arange(window[0],window[1]+1)\n    s,sc=at(source,indices,joints);p,pc=at(target,indices+lag,joints)\n    rows=[]\n    for epsilon in range(-2,3):\n        n,nc=at(target,indices+epsilon,joints)\n        valid=np.isfinite(s).all(-1)&np.isfinite(p).all(-1)&np.isfinite(n).all(-1)\n        w=np.where(valid,np.minimum(np.minimum(sc,pc),nc),0)\n        w=np.where(w>=threshold,w,0)\n        cp=d.costs(s,p,w);cn=d.costs(s,n,w)\n        row={\'null_lag\':epsilon,\'coverage\':float(valid.mean()),\'valid_frames\':int((w.sum(-1)>0).sum())}\n        if cp is None or cn is None or valid.mean()<.8 or (w.sum(-1)>0).sum()<8:\n            row[\'status\']=\'unknown_support\'\n        else:\n            row.update(status=\'measured\',raw_proposal_cost=cp[\'weighted_direction_error\'],raw_null_cost=cn[\'weighted_direction_error\'],centered_proposal_cost=cp[\'centered_direction_error\'],centered_null_cost=cn[\'centered_direction_error\'])\n            row[\'raw_gain\']=(row[\'raw_null_cost\']-row[\'raw_proposal_cost\'])/max(row[\'raw_null_cost\'],1e-8)\n            row[\'centered_gain\']=(row[\'centered_null_cost\']-row[\'centered_proposal_cost\'])/max(row[\'centered_null_cost\'],1e-8)\n        rows.append(row)\n    good=all(x[\'status\']==\'measured\' for x in rows)\n    return {\'null_comparisons\':rows,\'status\':\'measured\' if good else \'unknown\',\'min_raw_gain\':min(x[\'raw_gain\'] for x in rows) if good else None,\'min_centered_gain\':min(x[\'centered_gain\'] for x in rows) if good else None}\n\n\ndef main():\n    d.sanity()\n    # These are actual frozen proposals, taken from the archived original decisions.\n    cases=[(1,[44,59],\'left\',15,.7717598078189633),(3,[44,59],\'right\',14,.9211009775663938),(4,[40,55],\'right\',12,.9175034033404228),(10,[4,19],\'left\',21,.5116731856735194)]\n    rows=[]\n    for index,window,arm,lag,actual_gain in cases:\n        pose=ROOT/\'inputs\'/f\'index{index:02d}.pose.json\'\n        measurements={}\n        for threshold in [.3,.5]:\n            measurements[str(threshold)]=compare(d.directions(ROOT/\'inputs/source.pose.json\',threshold),d.directions(pose,threshold),window,arm,lag,threshold)\n        raw=min(x[\'min_raw_gain\'] for x in measurements.values())\n        assert abs(raw-actual_gain)<1e-10,(index,raw,actual_gain)\n        centered=min(x[\'min_centered_gain\'] for x in measurements.values())\n        row={\'index\':index,\'window\':window,\'arm\':arm,\'actual_proposal_lag\':lag,\'pose_sha256\':d.digest(pose),\'actual_min_raw_gain\':actual_gain,\'raw_gain_reproduced\':raw,\'min_centered_gain\':centered,\'passes_same_gain_threshold_0_5\':centered>.5,\'measurements\':measurements}\n        rows.append(row)\n        print(json.dumps({k:row[k] for k in [\'index\',\'window\',\'actual_proposal_lag\',\'raw_gain_reproduced\',\'min_centered_gain\',\'passes_same_gain_threshold_0_5\']}))\n    result={\'scope\':\'Fixed-trajectory, selected-proposal diagnostic only. Does not replay persistence, replace the observer or rerun a changed closed-loop trajectory.\',\'script_sha256\':d.digest(__file__),\'diagnostic_helpers_sha256\':d.digest(ROOT/\'diagnose.py\'),\'source_pose_sha256\':d.digest(ROOT/\'inputs/source.pose.json\'),\'existing_threshold_reused\':.5,\'new_threshold_tuning\':False,\'all_original_proposal_gains_reproduced\':True,\'rows\':rows}\n    (ROOT/\'CENTERED_SUPPORT_RESULT.json\').write_text(json.dumps(result,indent=2,allow_nan=False)+\'\\n\')\n\nif __name__==\'__main__\':main()\n', 'sha256': '42e5d2000584763743f75531a73171d6575c560a805de20e77e3a3e494092037', 'original_path': '/Users/researcher/DevProjects/h3-source-temporal-observability-20261020/check_centered_support.py'}}}
"""One CPU replay of a fixed observed trajectory, without modifying frozen code."""
import copy, hashlib, json, sys, time, types
from pathlib import Path

def sha(p):
    return hashlib.sha256(Path(p).read_bytes()).hexdigest()

def run(config):
    started=time.monotonic()
    root=Path(config['producer_root'])
    package=types.ModuleType('H3AutomaticWindowRouter')
    package.__path__=[str(root/'extensions/H3AutomaticWindowRouter')]
    sys.modules['H3AutomaticWindowRouter']=package
    from H3AutomaticWindowRouter.geometry import Geometry
    from H3AutomaticWindowRouter.selector import Controller
    from H3AutomaticWindowRouter.automatic_window_policy import candidate
    for name in ['diagnose','check_centered_support']:
        spec=config['helper_sources'][name]
        assert hashlib.sha256(spec['source'].encode()).hexdigest()==spec['sha256']
        mod=types.ModuleType(name);mod.__file__=spec['original_path']
        sys.modules[name]=mod
        exec(compile(spec['source'],spec['original_path'],'exec'),mod.__dict__)
    d=sys.modules['diagnose'];support=sys.modules['check_centered_support']
    d.sanity()
    audit_path=Path(config['audit_file'])
    assert sha(audit_path)==config['audit_sha256']
    data=json.loads(audit_path.read_text())['counterfactual']
    assert len(data['measurements'])==len(data['steps'])==20
    case=json.loads((root/'configs/protocol.json').read_text())['cases'][0]
    geometry=Geometry.from_case(case)
    source=Path(config['source_pose']);source_sha=sha(source)
    assert source_sha==config['source_pose_sha256']
    source_features={str(c):d.directions(source,c) for c in [.3,.5]}
    original=Controller(geometry,arm='visible_only')
    actual=[];bindings=[]
    # Complete first pass: prove all original decisions before any filtering.
    for i,m in enumerate(data['measurements']):
        ref=m['observer']['full_remote_record']
        assert sha(ref['file'])==ref['sha256']
        observer=json.loads(Path(ref['file']).read_text())
        assert observer['source_pose_sha256']==source_sha
        measurement=dict(m,observer=observer)
        decision=original.select(i,measurement)
        recorded=data['steps'][i]['decision']
        assert all(recorded[k]==v for k,v in decision.items()),('original_decision_mismatch',i)
        actual.append(decision)
        bindings.append({'index':i,'observer_sha256':ref['sha256'],'observer_path':ref['file'],'full_window_rows':len(observer['windows']),'response_sha256':m['response_sha256']})
    actual_on=[i for i,x in enumerate(actual) if x['active']]
    assert actual_on==[1,3,4,10,14,17,18],actual_on
    filtered=Controller(geometry,arm='visible_only');rows=[];max_raw_error=0.
    for i,m in enumerate(data['measurements']):
        observer=json.loads(Path(bindings[i]['observer_path']).read_text())
        response_path=Path(m['response_file']);assert sha(response_path)==m['response_sha256']
        response=json.loads(response_path.read_text())
        pose=Path(response['pose']['file']);pose_sha=sha(pose)
        assert pose_sha==response['pose']['sha256']==observer['edited_pose_sha256']
        bindings[i]['pose_sha256']=pose_sha
        raw_candidates=[(j,candidate(row)) for j,row in enumerate(observer['windows']) if candidate(row) is not None]
        features={str(c):d.directions(pose,c) for c in [.3,.5]} if raw_candidates else {}
        changed=copy.deepcopy(observer);details=[]
        for j,proposal in raw_candidates:
            row=observer['windows'][j]
            arm={'left_arm_direction':'left','right_arm_direction':'right','arm_direction':'both'}[row['feature']]
            comparisons={c:support.compare(source_features[c],features[c],row['window'],arm,int(proposal['lags'][c]),float(c)) for c in ['0.3','0.5']}
            measured=all(x['status']=='measured' for x in comparisons.values())
            if measured:
                raw=min(x['min_raw_gain'] for x in comparisons.values())
                delta=abs(raw-proposal['min_gain']);max_raw_error=max(max_raw_error,delta)
                assert delta<1e-10,('raw_gain_mismatch',i,row['window'],row['feature'],raw,proposal['min_gain'])
                gain=min(x['min_centered_gain'] for x in comparisons.values())
            else:
                raw=None;gain=None
            accepted=measured and gain>.5
            if not accepted:
                # Existing policy's candidate function rejects unknown status;
                # every accepted row and every original ranking score stays exact.
                changed['windows'][j]['status']='unknown'
            details.append({'window':row['window'],'feature':row['feature'],'lags':proposal['lags'],'original_min_gain':proposal['min_gain'],'centered_min_gain':gain,'accepted':accepted,'status':'measured' if measured else 'unknown_support','centered_gains_by_null_lag':{c:[v.get('centered_gain') for v in comparisons[c]['null_comparisons']] for c in comparisons}})
        new=filtered.select(i,dict(m,observer=changed))
        fields=['active','selected','physical_intervals','latent_bins','reason']
        rows.append({'index':i,'original':{k:actual[i][k] for k in fields},'filtered':{k:new[k] for k in fields},'accepted_count':sum(x['accepted'] for x in details),'rejected_count':sum(not x['accepted'] for x in details),'candidates':details})
    filtered_on=[x['index'] for x in rows if x['filtered']['active']]
    return {'schema':'r133-r138-full20-fixed-trajectory-centered-support-v1','scope':'Post-hoc replay of already observed ordinary predictions only. No changed closed-loop trajectory was generated.','support_definition':'Per proposal-versus-each-null-lag comparison, source/proposal/null use identical visible entries and minimum confidence weights; five comparisons can have different supports. Unchanged parent helper.','null_lags':list(range(-2,3)),'confidence_thresholds':[.3,.5],'added_eligibility':'minimum demeaned relative gain across both thresholds and all five null comparisons strictly > 0.5','ranking_and_persistence':'Original raw absolute-gain ranking, connected-component grouping and persistence code unchanged; rejected candidates alone set status unknown.','original_all20_decisions_exact':True,'actual_ON_indices':actual_on,'filtered_ON_indices':filtered_on,'main_action_ON_retained':[i for i in [1,3,4] if i in filtered_on],'static_ON_removed':[i for i in [10,14,17,18] if i not in filtered_on],'new_ON_indices':[i for i in filtered_on if i not in actual_on],'accepted_candidates':sum(x['accepted_count'] for x in rows),'rejected_candidates':sum(x['rejected_count'] for x in rows),'max_recomputed_raw_gain_error':max_raw_error,'bindings':bindings,'source_pose_sha256':source_sha,'audit_sha256':config['audit_sha256'],'helper_sha256':{k:v['sha256'] for k,v in config['helper_sources'].items()},'frozen_code_sha256':{n:sha(root/'extensions/H3AutomaticWindowRouter'/n) for n in ['selector.py','automatic_window_policy.py','delayed_window_policy.py','geometry.py','dynamic_support.py']},'CPU_wall_seconds':time.monotonic()-started,'rows':rows,'GPU_started':False,'pose_extraction':False,'new_threshold_search':False,'all_null_shared_support_variant':'Not run; explicitly kept original helper per-comparison definition.'}

if __name__=='__main__':
    output=run(CONFIG)
    encoded=json.dumps(output,ensure_ascii=False,separators=(',',':'),allow_nan=False)
    assert len(encoded.encode())<=200000,('result_too_large',len(encoded))
    print(encoded)
